// Регресс «готовность к выпуску 19.10.2026» — группа 6: без интернета.
// АВИАРЕЖИМ ВКЛЮЧАЕТ И ВЫКЛЮЧАЕТ ЧЕЛОВЕК (верхнюю шторку/Пункт управления тест не трогает). Запуск: QA_OFFLINE_MANUAL=1, иначе skip.
// Факты 19.10 (ac-status.md «Дополнение 19.10», readiness-report.html «Без интернета», снимки app/OFF-*.png):
// при открытом приложении без сети «תזכורות מהירות» на месте (F-36 AC1); «זמני תפילות» на новую дату —
// «לא הצלחנו לטעון את המיקום שנשמר» без примерного времени (F-54 AC5); молитва/תהילים/уроки не грузятся, холодный старт
// блокируется «בדיקת החשבון לא הסתיימה: אין תשובה מהשרת» — баг #48c24d61 (решение пользователя 19.10: без интернета — баг).
// ОБНОВЛЕНО 25.10: #48c24d61 (#7d0998) עבר QA — RD-06b/c: @known-bug → @passed-2510 (должны проходить). Текст «זמני תפילות» без сети
// теперь «אין חיבור לאינטרנט, ולכן זמני היום לא נטענו» (коммент 20.10, факт 25.10) — RD-06a ждёт его, старый «לא הצלחנו לטעון…» — регресс.
// Подробная офлайн-проверка 25.10 — specs/qa-2510/q-14-offline-saved-content-7d0998.e2e.ts.
// Кейсы: .qa/tests/readiness/RD-06-offline.md.
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, scrollToText } from '../../helpers/ui.ts';
import { skipWith, shown } from '../_lib/app-0710.ts';
import { appId } from '../_lib/app-1310b.ts';
import {
  goHome, openZmanim, zmanimRows, button, waitHuman, relaunch, openCatalogPrayer, saveShot,
} from '../_lib/readiness-1910.ts';

const NO_LOCATION = 'אין חיבור לאינטרנט, ולכן זמני היום לא נטענו';   // до 25.10: «לא הצלחנו לטעון את המיקום שנשמר»
const OLD_NO_LOCATION = 'לא הצלחנו לטעון את המיקום שנשמר';
const COLD_BLOCK = 'בדיקת החשבון לא הסתיימה';
const MANUAL_TIMEOUT = 1000000;

/** «השנה הבאה» до тех пор, пока «זמני תפילות» не покажет ошибку (новая, не загруженная дата) — признак, что сети нет. */
async function offlineZmanimError(): Promise<boolean> {
  for (let i = 0; i < 3; i++) {
    if (await shown(byTextContains(NO_LOCATION))) return true;
    await (await button('השנה הבאה')).click().catch(() => {});
    await driver.waitUntil(async () => shown(byTextContains(NO_LOCATION)), { timeout: 5000 }).catch(() => {});
  }
  return shown(byTextContains(NO_LOCATION));
}

describe('Готовность 19.10 — без интернета (ручной авиарежим)', () => {
  before(function () {
    if (process.env.QA_OFFLINE_MANUAL !== '1') skipWith(this, 'авиарежим включает человек — запуск с QA_OFFLINE_MANUAL=1 и человеком у телефона');
  });

  it('RD-06a Приложение открыто, сеть пропала: «זמני תפילות» на новую дату — «אין חיבור לאינטרנט, ולכן זמני היום לא נטענו», без времени; «תזכורות מהירות» на главной F-54 AC5 F-36 AC1 @manual-check @prod-safe', async function () {
    this.timeout(1200000);
    await openZmanim();
    await waitHuman('включите АВИАРЕЖИМ (приложение не закрывать). Тест листает «השנה הבאה», пока не увидит ошибку загрузки.',
      async () => offlineZmanimError());
    const rows = await zmanimRows();
    const timed = rows.filter((r) => /^\d{1,2}:\d{2}$/.test(r.time));
    expect(timed.length).toBe(0);                    // F-54 AC5: без примерного времени
    expect(await shown(byTextContains(OLD_NO_LOCATION))).toBe(false);   // сообщение про связь, не про место (#48c24d61)
    await saveShot('OFF-zmanim-new-date.png');
    await goHome();
    await scrollToText('תזכורות מהירות');
    await expect(byText('תזכורות מהירות')).toBeDisplayed();   // F-36 AC1
  });

  it('RD-06b Без сети молитва открывается с текстом (из каталога) #48c24d61 #7d0998 @passed-2510 @manual-check @prod-safe', async function () {
    this.timeout(600000);
    // 19.10: «לא הצלחנו לטעון…» и «נסו שוב» вместо текста молитвы. 25.10: ранее открытая молитва читается (שחרית должна быть открыта онлайн до авиарежима).
    await openCatalogPrayer('שחרית');
    await expect(byTextMatches('.*[\\u05B0-\\u05C7].*')).toBeExisting({ wait: 20000 });
  });

  it('RD-06c Холодный старт без сети — главная, без «בדיקת החשבון לא הסתיימה» #48c24d61 #7d0998 @passed-2510 @manual-check @prod-safe', async function () {
    this.timeout(600000);
    await driver.terminateApp(appId()).catch(() => {});
    await driver.activateApp(appId());
    let home = false;
    await driver.waitUntil(async () => (home = await shown(byText('בית'))) || (await shown(byTextContains(COLD_BLOCK))),
      { timeout: 60000, interval: 1500 }).catch(() => {});
    await saveShot('OFF-cold-start.png');
    expect(await shown(byTextContains(COLD_BLOCK))).toBe(false);
    expect(home).toBe(true);
  });

  after(async function () {
    this.timeout(MANUAL_TIMEOUT);
    if (process.env.QA_OFFLINE_MANUAL !== '1') return;
    await waitHuman('ВЫКЛЮЧИТЕ авиарежим. Тест перезапускает приложение, пока не откроется главная.', async () => {
      try { await relaunch(); return true; } catch { return false; }
    });
    await goHome();
  });
});
